function art(kind='book',dark=false){
  if(!['book','page','table'].includes(kind))return sceneArt(kind,dark);
  const bg=dark?'#444c3e':kind==='table'?'#e8deca':'#dfe5d8';
  const shadow=dark?'#222c20':'#b6bca7';
  const book=dark?'#afb783':'#5d7253';
  const label=kind==='page'?'ONE GOOD\nSENTENCE':'A LITTLE\nROOM';
  const base=`<rect width="480" height="340" fill="${bg}"/><path d="M325 0h155v340H380L180 0Z" fill="${dark?'#737959':'#fffaf0'}" opacity=".24"/><path d="M0 254c160-31 251-25 480 18v68H0Z" fill="${dark?'#303b30':'#d1ccb9'}" opacity=".38"/>`;
  const mug=`<ellipse cx="370" cy="260" rx="44" ry="12" fill="${shadow}" opacity=".25"/><ellipse cx="365" cy="243" rx="38" ry="10" fill="#eee9dc"/><path d="M337 188v44q3 20 28 20t28-20v-44Z" fill="#eee9dc"/><path d="M391 197q29-4 27 16-1 17-28 16" fill="none" stroke="#ddd8c9" stroke-width="9"/><ellipse cx="365" cy="188" rx="28" ry="9" fill="#dcd2ba"/><ellipse cx="365" cy="188" rx="22" ry="6" fill="#745741"/>`;
  let obj;
  if(kind==='page') obj=`<g transform="translate(94 63) rotate(-7 140 104)"><ellipse cx="151" cy="229" rx="148" ry="14" fill="${shadow}" opacity=".28"/><path d="M0 14Q65-7 137 10v199q-73-17-137 0Z" fill="#f4efdf"/><path d="M137 10q77-16 143 4v195q-65-13-143 0Z" fill="#fffae9"/><path d="M137 12v195" stroke="#bcb6a0"/><g stroke="#b7b29d" stroke-width="2" opacity=".75">${[45,60,75,90,105,120,135,150,165].map(y=>`<path d="M23 ${y}h92m45 0h95"/>`).join('')}</g><path d="M24 103h87m48 31h93" stroke="#c6ae66" stroke-width="9" opacity=".5"/><path d="m225 1-7 43 11-5 10 8 7-44" fill="#926850"/></g>`;
  else obj=`<g transform="translate(${kind==='table'?'92 53':'112 45'}) rotate(-12 115 124)"><ellipse cx="121" cy="262" rx="105" ry="12" fill="${shadow}" opacity=".25"/><rect x="-3" y="8" width="193" height="245" rx="6" fill="#9ba28b"/><rect x="5" y="8" width="183" height="238" rx="4" fill="#ede8d8"/><rect width="191" height="239" rx="5" fill="${book}"/><path d="M8 0v239" stroke="#263d27" opacity=".3"/><path d="M30 35h124" stroke="#e3d5af" stroke-width="1" opacity=".6"/><text x="98" y="78" text-anchor="middle" fill="#f5edcf" font-family="Georgia,serif" font-size="25">${label.split('\n')[0]}</text><text x="98" y="108" text-anchor="middle" fill="#f5edcf" font-family="Georgia,serif" font-size="25">${label.split('\n')[1]}</text><path d="M56 157q36-40 74 0m-70 0q35 25 69 0" fill="none" stroke="#d3c59f" stroke-width="1.5"/><circle cx="96" cy="151" r="5" fill="#d3c59f"/><text x="96" y="213" text-anchor="middle" fill="#ede1c0" font-family="sans-serif" font-size="7" letter-spacing="3">NOTES ON EVERYDAY LIFE</text></g>`;
  return `<svg class="paper-art" viewBox="0 0 480 340" role="img" aria-label="Illustrated reference for ${kind==='page'?'an open book with a highlighted sentence':kind==='table'?'a book and a cup beside a window':'a book cover beside a cup'}">${base}${obj}${mug}<path d="M0 0h40L0 128Z" fill="#fff" opacity=".18"/></svg>`;
}

