Object.assign(packages, {
  food:{title:'The lunch I make on autopilot',hook:'This is what I make when I have no energy to decide what to eat.',format:'Reel',minutes:5,duration:20,label:'Food & everyday life',why:'Use your usual lunch. You do not need a new recipe or a perfect kitchen.',art:'food',tags:'#EasyLunch #EverydayCooking',caption:'The lunch I make on autopilot. Something warm, a few things I already have, and no big decision.\n\nWhat is your no-thinking lunch?',shots:[{name:'What is already in the kitchen',duration:'0–4 sec',art:'food',instruction:'Set two or three ingredients on the counter. Film a close-up from above in natural light.',words:'This is what I make when I have no energy to decide what to eat.',overlay:'My no-thinking lunch.'},{name:'One satisfying step',duration:'4–13 sec',art:'food',instruction:'Film one action: stirring, chopping, or placing food on a plate. Keep the phone safely away from heat.',words:'A few things I already have. One pan. Nothing complicated.',overlay:'Use what you have.'},{name:'The finished plate',duration:'13–20 sec',art:'food',instruction:'Place the finished plate by a window. Film one still shot, then add the last line as voiceover.',words:'Good enough to make again tomorrow. What is your no-thinking lunch?',overlay:'What is your go-to?'}]},
  travel:{title:'A place I almost walked past',hook:'I almost walked past this. I am glad I stopped for a minute.',format:'Reel',minutes:5,duration:20,label:'Travel & small discoveries',why:'Use a place on your usual route. You do not need a special trip.',art:'travel',tags:'#LittleDiscoveries #TravelSlow',caption:'A place I almost walked past. A quiet corner, a little detail, and one minute of paying attention.\n\nWhat have you found by slowing down?',shots:[{name:'The place from a few steps away',duration:'0–5 sec',art:'travel',instruction:'Stand still and film the place from outside. Keep people out of frame where possible.',words:'I almost walked past this.',overlay:'Almost missed this.'},{name:'The detail worth stopping for',duration:'5–13 sec',art:'travel',instruction:'Film a closer view of the sign, doorway, or small detail that caught your attention.',words:'Nothing dramatic. Just a little corner that made me stop.',overlay:'Look a little closer.'},{name:'Your recommendation',duration:'13–20 sec',art:'travel',instruction:'Film a last wide shot. Add your recommendation as voiceover or text.',words:'I am glad I stayed for a minute. What have you found by slowing down?',overlay:'Worth a small detour.'}]},
  fitness:{title:'The small workout I still show up for',hook:'On a low-energy day, this is enough for me.',format:'Reel',minutes:5,duration:20,label:'Fitness & everyday routines',why:'Show a familiar routine at your own pace. No new workout is needed.',art:'fitness',tags:'#SmallSteps #EverydayMovement',caption:'On a low-energy day, this is enough for me. A familiar routine, a little movement, and no pressure to turn it into something bigger.\n\nWhat helps you show up?',shots:[{name:'Make a little room',duration:'0–5 sec',art:'fitness',instruction:'Film your mat, shoes, or water bottle. Use an exercise you already know.',words:'On a low-energy day, this is enough for me.',overlay:'A little still counts.'},{name:'One familiar movement',duration:'5–14 sec',art:'fitness',instruction:'Record a short part of your usual routine. Choose a camera position that stays clear of your movement.',words:'One familiar movement. No big plan. Just showing up.',overlay:'Keep it familiar.'},{name:'After the small effort',duration:'14–20 sec',art:'fitness',instruction:'Film putting your equipment away or having a drink of water.',words:'Some days, that is the whole win. What helps you show up?',overlay:'That is enough for today.'}]},
  movies:{title:'The film I keep recommending',hook:'There is one scene in this film I still think about.',format:'Reel',minutes:5,duration:20,label:'Movies & TV',why:'Share your own reaction without needing film clips.',art:'movies',tags:'#MovieTalk #FilmRecommendations',caption:'There is one scene in this film I still think about. Not because it was the loudest moment, but because it felt real.\n\nWhat film has stayed with you?',shots:[{name:'Set up your recommendation',duration:'0–5 sec',art:'movies',instruction:'Film your own viewing setup or speak to camera. Add the film title as text.',words:'There is one scene in this film I still think about.',overlay:'A film that stayed with me.'},{name:'Explain the feeling',duration:'5–14 sec',art:'table',instruction:'Record your reaction without showing film footage. Keep the explanation free of spoilers.',words:'It was a small moment. But it made the whole story feel real.',overlay:'No spoilers. Just a feeling.'},{name:'Invite another recommendation',duration:'14–20 sec',art:'movies',instruction:'Film a quiet closing shot or stay on camera for the final question.',words:'That is why I keep recommending it. What film has stayed with you?',overlay:'What should I watch next?'}]},
  style:{title:'The detail that makes an outfit feel like me',hook:'This is the small detail I always come back to.',format:'Reel',minutes:5,duration:20,label:'Style & everyday choices',why:'Use an outfit you already wear. No shopping or styling session needed.',art:'style',tags:'#PersonalStyle #EverydayOutfit',caption:'This is the small detail I always come back to. A familiar outfit, one piece I love, and a little more of me.\n\nWhat is your signature detail?',shots:[{name:'Your everyday outfit',duration:'0–5 sec',art:'style',instruction:'Lay the outfit on your bed or film a still mirror shot.',words:'This is the small detail I always come back to.',overlay:'The little detail.'},{name:'The piece you love',duration:'5–14 sec',art:'style',instruction:'Film a closer view of the colour, accessory, or texture you chose.',words:'Nothing new. Just a piece that makes the whole thing feel like me.',overlay:'A little more me.'},{name:'The finished look',duration:'14–20 sec',art:'style',instruction:'Film the final outfit in natural light. Add your closing question.',words:'What is your signature detail?',overlay:'What is your signature detail?'}]},
  art:{title:'The part of making something I love most',hook:'This is my favourite part of making something.',format:'Reel',minutes:5,duration:20,label:'Art & creativity',why:'Capture a work in progress. The finished result is optional.',art:'art',tags:'#CreativeProcess #WorkInProgress',caption:'This is my favourite part of making something. The small choices before it all comes together.\n\nStill a work in progress. That is part of the good bit.',shots:[{name:'Before you begin',duration:'0–5 sec',art:'art',instruction:'Film the tools or materials already on your desk.',words:'This is my favourite part of making something.',overlay:'The good bit.'},{name:'One small decision',duration:'5–14 sec',art:'art',instruction:'Record a few seconds of sketching, arranging, or choosing a colour.',words:'The small choices. The things you notice before it all comes together.',overlay:'One small choice at a time.'},{name:'A work in progress',duration:'14–20 sec',art:'art',instruction:'Show the piece as it is now. You do not need to finish it for this post.',words:'Still a work in progress. That is part of the good bit.',overlay:'You can share the process.'}]},
});
const topicIdeas = {'Books':'book','Everyday life':'routine','Food':'food','Travel':'travel','Fitness':'fitness','Style':'style','Movies & TV':'movies','Art & creativity':'art'};
const state = {variant:'A',screen:'today',stage:'ready',idea:'book',shot:0,done:new Set(),scenario:'ready',onboardingStep:'welcome',planDay:0,plans:{},lastSavedDay:1,saveDay:1,alternativeTarget:null,interests:new Set(['Books']),setupInterests:new Set(),startingPoint:'Just starting',time:'10 min',voice:'Voiceover',format:'Reel',tone:'Thoughtful',platform:'Instagram',name:'Iris',context:'',customTopic:'',references:[],referenceName:'',referenceUrl:'',reminder:false,reminderTime:'09:00',history:[],captionDrafts:{},scriptDrafts:{},includeTags:true,firstIdea:false,preference:'interests',tourStep:0,compare:false};
const query = new URLSearchParams(location.search);
if (directions[query.get('variant')?.toUpperCase()]) state.variant=query.get('variant').toUpperCase();
if (query.get('flow')==='onboarding') {state.scenario='onboarding';state.onboardingStep=query.get('step')==='setup'?'topics':'welcome';}
if (query.get('flow')==='plan'||query.get('flow')==='you') state.screen=query.get('flow');
let toastTimeout, keyboardAction=false, lastFocused, preparationToken=0, sheetDraft=null;
state.preferenceSnapshot=null;
const phone=document.querySelector('#phone'), app=document.querySelector('#app'), sheet=document.querySelector('#sheet');
const current=()=>{const p=packages[state.idea];return {...p,caption:state.captionDrafts[state.idea]??p.caption,shots:p.shots.map((s,i)=>({...s,words:state.scriptDrafts[state.idea]?.[i]??s.words}))};};
const primary=(label,action,iconName='arrow')=>`<button class="primary" data-action="${action}">${label}${icon(iconName)}</button>`;
const secondary=(label,action)=>`<button class="secondary" data-action="${action}">${label}</button>`;
const textAction=(label,action,iconName)=>`<button class="text-action" data-action="${action}">${iconName?icon(iconName):''}${label}</button>`;
const meta=(p=current())=>`<div class="meta-row"><span>${icon('film')}${p.duration?`${p.duration}-sec ${p.format}`:p.format}</span><span>${icon('clock')}${p.minutes} min to make</span><span>${p.shots.length?`${p.shots.length} shots`:'No filming'}</span></div>`;
const captionText=(p=current())=>p.caption+(state.includeTags&&p.tags?'\n\n'+p.tags:'');
const dayName=(i)=>`${days[i].name} · ${days[i].day}, ${days[i].date} October`;
const initial=()=>escapeText(state.name.trim().slice(0,1).toUpperCase()||'I');

