    art:`<g transform="rotate(-8 231 188)"><rect x="105" y="76" width="252" height="223" rx="7" fill="#f3ead7"/><path d="M129 232q39-133 74-41t49-46q45-94 73 95" fill="none" stroke="#7c9677" stroke-width="10"/><path d="m143 116 81 5m33-3 61 11" stroke="#c59569" stroke-width="7"/></g><path d="m374 107-9 197" stroke="#a47751" stroke-width="9" stroke-linecap="round"/><path d="m376 84-9 36q18 15 18-8Z" fill="#697f61"/><path d="m404 126-6 178" stroke="#c8a375" stroke-width="7"/>`,
