function header(title='Today'){return `<header class="app-header"><div><h2>${title}</h2><div class="date">Friday, 2 October</div></div><button class="avatar-btn" data-action="you" aria-label="Open your profile">${initial()}</button></header>`;}
function nav(){const selected=state.screen==='preferences'?'you':state.screen;return `<nav class="bottom-nav" aria-label="App navigation">${[['today','Today','sun'],['plan','Plan','calendar'],['you','You','user']].map(([a,b,c])=>`<button data-action="${a}" ${selected===a?'aria-current="page"':''}>${icon(c)}${b}</button>`).join('')}</nav>`;}
function shotPreview(p=current()){return `<div class="section-heading"><h3>Your filming plan</h3><span>${p.shots.length} simple shots</span></div>${p.shots.map((s,i)=>`<button class="shot-row" data-shot="${i}" aria-label="Open shot ${i+1}: ${s.name}"><div class="shot-thumb">${art(s.art)}</div><div><h3>${s.name}</h3><p>${s.duration} · ${state.done.has(i)?'Done':'Ready to film'}</p></div><span class="shot-num">0${i+1}</span></button>`).join('')}`;}
function dailyDetails(){const p=current();return `<div class="content-padding"><div class="daily-tools"><button class="tool-tile" data-action="script">${icon('text')}<span>Full script</span></button><button class="tool-tile" data-action="post">${icon('copy')}<span>Post text</span></button><button class="tool-tile" data-action="save-plan">${icon('bookmark')}<span>Save for later</span></button></div><div class="reason-note"><span class="eyebrow">Made for your day</span><p>${p.why}</p><div class="preference-summary"><span>${escapeText(state.voice)}</span><span>${escapeText(state.tone)}</span><span>${escapeText(state.platform)}</span></div></div><button class="tomorrow-peek" data-action="plan-tomorrow">${icon('calendar')}<span><strong>Tomorrow, a little easier</strong><small>${state.plans[1]?packages[state.plans[1]].title:'Leave one idea ready for your next day.'}</small></span>${icon('right')}</button></div>`;}
function firstIdeaNote(){return state.firstIdea?`<div class="first-idea-note">${icon('sparkle')}<span><strong>Your first idea is ready.</strong><small>Everything you need is right here.</small></span><button class="text-action" data-action="tour">Quick tour</button></div>`:'';}
function readyA(){const p=current();return `${header()}${firstIdeaNote()}<div class="content-padding"><article class="pocket-hero"><div class="pocket-art-wrap">${art(p.art)}<span class="art-label">${icon('sparkle')} PICKED FOR YOU</span></div><div class="pocket-hero-copy"><span class="eyebrow">${p.label}</span><h2>${p.title}</h2><p class="hook">“${p.hook}”</p>${meta(p)}</div></article><div class="pocket-alt">${textAction('Need something easier?','alternatives','refresh')}</div>${p.shots.length?shotPreview(p):`<div class="instruction-block"><span class="eyebrow">A photo you already have</span><p>No new footage. Your caption is ready.</p></div>`}</div>${dailyDetails()}`;}
function readyB(){const p=current();return `<header class="daybook-header"><span class="daybook-brand">your daybook.</span><span class="date">FRI, OCT 02</span></header>${firstIdeaNote()}<div class="daybook-title"><span class="eyebrow">A little idea for today</span><h2>${p.title}</h2>${meta(p)}</div><div class="daybook-quote"><div class="eyebrow">Start with this</div><p>“${p.hook}”</p></div><div class="daybook-illustration">${art(p.art)}<span class="print-label">${p.shots.length?'01 — THE OPENING SHOT':'01 — SOMETHING FROM YOUR DAY'}</span></div><div class="daybook-footer"> ${textAction('Something lighter today','alternatives')}</div><div class="content-padding">${p.shots.length?shotPreview(p):''}</div>${dailyDetails()}`;}
function readyC(){const p=current();return `<header class="studio-header"><span class="studio-brand"><span class="studio-dot"></span>studio.</span><span class="date">FRIDAY / 02 OCT</span></header>${firstIdeaNote()}<div class="studio-heading"><span class="eyebrow">TODAY’S TAKE · ${p.format.toUpperCase()}</span><h2>${p.title}</h2>${meta(p)}</div><div class="studio-script"><span class="eyebrow">${p.shots.length?'THE OPENING LINE':'THE CAPTION'}</span><p>“${p.hook}”</p></div><div class="studio-frame">${art(p.art,true)}<div class="viewfinder"></div><div class="viewfinder-top"><span>OPENING FRAME</span><span>${p.duration?`00:${String(p.duration).padStart(2,'0')}`:'PHOTO'}</span></div><span class="frame-bottom">${p.shots.length?'SHOT 01 · Natural light':'YOUR CAMERA ROLL · No filming'}</span></div>${p.shots.length?`<div class="studio-timeline">${p.shots.map((s,i)=>`<span class="time-segment">0${i+1} · ${s.duration}</span>`).join('')}</div>`:''}<div class="studio-footer">${textAction('Change the plan','alternatives','refresh')}</div><div class="content-padding">${p.shots.length?shotPreview(p):''}</div>${dailyDetails()}`;}
function readyD(){const p=current();return `<header class="cue-top"><span class="wordmark">cue<span style="opacity:.35">.</span></span><span class="date">Friday, 2 Oct</span></header>${firstIdeaNote()}<div class="cue-task"><div class="cue-task-head">${icon('sparkle')}<span class="eyebrow">Your idea for today</span><span class="format-chip">${p.format}</span></div><h2 class="cue-title">${p.title}</h2>${meta(p)}</div><div class="cue-main"><span class="eyebrow">${icon('mic')} ${p.shots.length?'YOUR FIRST LINE':'YOUR CAPTION STARTS HERE'}</span><blockquote>“${p.hook}”</blockquote><p class="read-note">${p.shots.length?'Say it like you’re telling a friend. No perfect take needed.':'Pair it with a photo you already like. No new filming.'}</p></div><div class="cue-task-row"><div class="shot-thumb">${art(p.art)}</div><div><h3>${p.shots.length?'Start with one simple shot':'Use something you already have'}</h3><p>${p.shots[0]?.name||'A recent photo from your camera roll.'}</p></div></div><div class="cue-footer"><div class="cue-links">${textAction('Read full script','script')}${textAction('Other ideas','alternatives')}</div></div><div class="content-padding">${p.shots.length?shotPreview(p):''}</div>${dailyDetails()}`;}
const readyViews={A:readyA,B:readyB,C:readyC,D:readyD};
function readyAction(variant=state.variant){const p=current();return primary(p.shots.length?{A:'Start filming',B:'Let’s make this',C:'Start take one',D:'Show me the shots'}[variant]:(variant==='B'?'Use this caption':'Get post text'),p.shots.length?'film':'post',variant==='C'||variant==='D'?(p.shots.length?'camera':'arrow'):'arrow');}

function welcomeActions(){return `<div class="welcome-actions"><button class="primary apple-button" data-action="preview-sign-in"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M15.7 2.8c.1 1.4-.5 2.7-1.3 3.5-.8.8-2 1.4-3.2 1.3-.2-1.2.5-2.6 1.3-3.4.9-.9 2.2-1.4 3.2-1.4Z" fill="currentColor" stroke="none"/><path d="M17.5 12.2c0-2 1.7-3 1.8-3.1-1-1.5-2.6-1.7-3.2-1.8-1.4-.2-2.8.9-3.5.9-.7 0-1.8-.9-3-.8-1.6 0-3.1.9-3.9 2.3-1.7 2.8-.4 6.9 1.2 9.2.8 1.1 1.6 2.4 2.8 2.3 1.1 0 1.6-.7 3-.7 1.4 0 1.8.7 3.1.7 1.3 0 2.1-1.1 2.9-2.3.9-1.4 1.3-2.7 1.3-2.8-.1 0-2.5-1-2.5-3.9Z" fill="currentColor" stroke="none"/></svg>Sign in with Apple</button>${textAction('How does it work?','tour')}<p class="privacy-note">One account for your ideas and preferences.<br>No social account connection needed.</p></div>`;}
function welcomeView(){
  const benefits=`<div class="welcome-benefits"><div>${icon('sparkle')}<span>An idea picked for your day</span></div><div>${icon('film')}<span>The shots and words, already ready</span></div><div>${icon('clock')}<span>A small plan that fits real life</span></div></div>`;
  const variants={
    A:`<div class="welcome-stack">${art('book')}<div class="welcome-note"><span class="eyebrow">A little something for today</span><strong>The book I almost put down</strong><span>3 shots · 8 minutes · All you need</span></div></div><span class="eyebrow">Your daily creative companion</span><h2>Less thinking.<br>More making.</h2><p>Open the app. Find one good idea. Make something that feels like you.</p>${benefits}`,
    B:`<div class="welcome-letter"><span class="eyebrow">A page for your creative life</span><h2>Something worth<br>sharing, every day.</h2><p>You bring your everyday life.<br>We bring a little starting point.</p>${art('table')}<span class="eyebrow">A thought. A few shots. Your own words.</span></div>`,
    C:`<span class="eyebrow">CONTENTHELPER / YOUR POCKET STUDIO</span><div class="welcome-viewfinder">${art('book',true)}<div class="viewfinder"></div><span class="frame-bottom">TODAY’S IDEA / READY TO ROLL</span></div><h2>Your next take<br>starts here.</h2><p>The opening line, the shots, the caption. One clear plan. Then you make it yours.</p><div class="welcome-spec"><span><strong>01</strong> IDEA</span><span><strong>03</strong> SHOTS</span><span><strong>08</strong> MINUTES</span></div>`,
    D:`<span class="eyebrow">You already have something to say</span><div class="welcome-cue"><span>${icon('mic')} YOUR FIRST LINE COULD BE</span><blockquote>“I nearly gave up on this book. Then one line changed my mind.”</blockquote></div><h2>Find your words.<br>Hit record.</h2><p>A little help with where to start. The rest can sound exactly like you.</p><div class="welcome-demo">${icon('check')} One idea. A script. A simple shot list.</div>`,
  };
  return `<div class="welcome-panel welcome-${state.variant}">${variants[state.variant]}</div>`;
}
function topicButtons(selected,setup=false){return `<div class="topic-grid">${topics.map(([label,symbol])=>`<button class="topic-choice" data-interest="${label}" data-setup="${setup}" aria-pressed="${selected.has(label)}">${icon(symbol)}<span>${label}</span>${selected.has(label)?icon('check'):''}</button>`).join('')}${!setup&&[...selected].filter(x=>!topics.some(([t])=>t===x)).map(x=>`<button class="topic-choice" data-interest="${escapeText(x)}" aria-pressed="true">${icon('sparkle')}<span>${escapeText(x)}</span>${icon('check')}</button>`).join('')}</div>`;}
function setupView(){return `<div class="setup-header"><button class="icon-btn" data-action="onboarding-back" aria-label="Back to welcome">${icon('left')}</button><span class="eyebrow">A little about you</span><span class="format-chip">Optional</span></div><div class="setup-content"><h2>What do you<br>love sharing?</h2><p>Pick what comes naturally. One interest is enough to start. You can change this later.</p>${topicButtons(state.setupInterests,true)}<label class="field-label">Where are you starting?</label><div class="starting-point">${['Just starting','Already posting'].map(x=>`<button data-set="startingPoint" data-value="${x}" aria-pressed="${state.startingPoint===x}">${x}</button>`).join('')}</div><div class="reason-note"><span class="eyebrow">No perfect profile needed</span><p>Your first idea comes with a script, shots, and a caption. Add more preferences in You whenever you want.</p></div></div>`;}
function emptyView(){return `${header()}<div class="empty-content"><div class="empty-art">${icon('sparkle')}</div><span class="eyebrow">A fresh start</span><h2>Let’s find your<br>idea for today.</h2><p>We’ll use your interests and keep it simple. You won’t need to write a prompt.</p>${primary('Prepare today’s idea','prepare','sparkle')}${textAction('Change my interests','interests')}<div class="preference-summary"><span>${escapeText([...state.interests].join(' · ')||'Everyday life')}</span><span>${state.time}</span><span>${state.voice}</span></div></div>`;}
function preparingView(){return `${header()}<div class="preparing-content"><div class="success-mark">${icon('sparkle')}</div><span class="eyebrow">One small starting point</span><h2>Preparing your<br>${state.firstIdea?'first idea':'idea for today'}.</h2><p>Something you can make with the time and things you already have.</p><div class="preparing-list"><div>${icon('check')} Your interests</div><div>${icon('check')} A clear opening line</div><div>${icon('check')} Shots, script, and caption</div></div><p class="film-note">This is a preview of the preparation screen.</p></div>`;}
function errorView(){return `${header()}<div class="preparing-content"><div class="success-mark">${icon('refresh')}</div><span class="eyebrow">A small pause</span><h2>Your idea needs<br>another moment.</h2><p>Your preferences are safe. Try again, or use a simple idea that is already ready.</p><div class="retry-panel">${primary('Try again','prepare','refresh')}${secondary('Use a simple starter idea','use-starter')}</div>${textAction('Check my preferences','you')}</div>`;}
function filmView(){const p=current(),s=p.shots[state.shot];return `<div class="screen-topline"><button class="icon-btn" data-action="back-ready" aria-label="Back to today’s idea">${icon('left')}</button><h2>Shot ${state.shot+1} of ${p.shots.length}</h2>${textAction('Script','script')}</div><div class="shot-jump" aria-label="Filming steps">${p.shots.map((_,i)=>`<button data-shot="${i}" ${state.shot===i?'aria-current="step"':''} aria-label="Go to shot ${i+1}">${state.done.has(i)?icon('check'):String(i+1).padStart(2,'0')}</button>`).join('')}<span class="shot-counter">${state.done.size} of ${p.shots.length} done</span></div><div class="film-content">${art(s.art,state.variant==='C')}<span class="eyebrow">${s.duration} · ${state.done.has(state.shot)?'SHOT COMPLETE':'YOUR NEXT SHOT'}</span><h2>${s.name}</h2><p class="shot-instruction">${s.instruction}</p><div class="shot-checklist"><span>${icon('check')} Portrait · phone camera</span><span>${icon('check')} One steady take is enough</span></div><div class="instruction-block"><span class="eyebrow">${state.voice==='No talking'?'Use as on-screen text':'Say this'}</span><p>“${escapeText(s.words)}”</p></div><div class="instruction-block"><span class="eyebrow">On-screen text</span><p>${s.overlay}</p></div>${textAction('Adjust these words','edit-script','text')}<p class="film-note">Record in your camera app. Come back to mark the shot done.</p></div>`;}
function postView(){const p=current();return `<div class="screen-topline"><button class="icon-btn" data-action="back-ready" aria-label="Back to today’s idea">${icon('left')}</button><h2>Ready to post</h2>${textAction('Preview','social-preview')}</div><div class="post-header"><span class="eyebrow">Your words are ready</span><h2>Make it yours.<br>Then share it.</h2><p>Copy the caption and share in your usual app. Mark it posted when you are done.</p></div><div class="content-padding"><div class="platform-tabs" aria-label="Posting platform">${['Instagram','TikTok','YouTube'].map(x=>`<button data-set="platform" data-value="${x}" aria-pressed="${state.platform===x}">${x}</button>`).join('')}</div></div><div class="copy-card"><div class="eyebrow">Caption · ${p.caption.length} characters</div><div class="caption-text">${escapeText(p.caption)}</div>${state.includeTags&&p.tags?`<div class="caption-tags">${p.tags}</div>`:''}<div class="caption-actions">${textAction('Edit caption','edit-caption','text')}${p.tags?`<label class="tag-toggle"><span>Hashtags</span><button role="switch" aria-label="Include hashtags" aria-checked="${state.includeTags}" data-action="toggle-tags">${state.includeTags?'On':'Off'}</button></label>`:''}</div><button class="secondary" data-action="copy-caption">${icon('copy')} Copy caption</button></div><div class="small-info">${icon(p.shots.length?'headphones':'camera')}<p>${p.shots.length?'Put the shots in order. Keep your voice clear and background music quiet.':'Choose a photo you already like. No new recording needed.'}</p></div><div class="content-padding"><div class="reason-note"><span class="eyebrow">A final look</span><p>Check your words, add the film or photo, and share when it feels ready.</p></div></div>`;}
function successView(){const p=current();return `<div class="success-content"><div class="success-mark">${icon('check')}</div><span class="eyebrow">Today · Posted</span><h2 style="margin-top:13px">One less thing<br>on your mind.</h2><p>You marked this as posted.<br>Your idea and caption are saved here.</p><div class="result-summary"><div class="shot-thumb">${art(p.art)}</div><div><h3>${p.title}</h3><p>${p.format} · Friday, 2 October</p></div></div>${secondary('View the caption','post')}${textAction('Undo posted status','undo-posted')}<div class="instruction-block" style="margin-top:23px;text-align:left"><span class="eyebrow">Make tomorrow easier</span><p style="font-size:13px">${state.plans[1]?'You already have an idea saved for tomorrow.':'Leave tomorrow’s idea ready when you have a moment.'}</p>${textAction('Take a look at tomorrow','plan-tomorrow','arrow')}</div></div>`;}
function savedView(){return `<div class="success-content"><div class="success-mark">${icon('bookmark')}</div><span class="eyebrow">${dayName(state.lastSavedDay)}</span><h2 style="margin-top:13px">Room for<br>another day.</h2><p>This idea is now in your plan.<br>Today can stay simple.</p><div class="result-summary"><div class="shot-thumb">${art(current().art)}</div><div><h3>${current().title}</h3><p>Saved for ${days[state.lastSavedDay].day}, ${days[state.lastSavedDay].date} October</p></div></div>${primary('Find a lighter idea for today','alternatives','refresh')}${textAction('View the saved day','open-saved-day')}</div>`;}
function planView(){const id=state.planDay===0?state.idea:state.plans[state.planDay],p=id?packages[id]:null;return `${header('Plan')}<p class="plan-intro">A little something ready for your next day. No weekly strategy session needed.</p><div class="plan-summary"><span>${Object.keys(state.plans).length} future ${Object.keys(state.plans).length===1?'idea':'ideas'} ready</span><span>Today · ${state.history.includes(state.idea)?'Posted':'Idea ready'}</span></div><div class="week-strip" aria-label="Choose a day">${days.map((d,i)=>`<button class="week-day" data-plan-day="${i}" aria-label="${d.day} ${d.date} October" aria-pressed="${state.planDay===i}"><span>${d.day}</span><strong>${d.date}</strong><span class="day-dot ${i===0||state.plans[i]?'is-ready':''}" aria-hidden="true"></span></button>`).join('')}</div><div class="plan-day-details"><span class="eyebrow">${dayName(state.planDay)}</span>${p?`<div class="plan-card"><span class="format-chip">${state.history.includes(id)&&state.planDay===0?'Posted':'Idea ready'}</span><h3>${p.title}</h3><p>“${p.hook}”</p>${meta(p)}${primary(state.planDay===0?'Open today’s idea':'View the full idea','open-plan-idea')}<div class="plan-detail-art">${art(p.art,state.variant==='C')}</div>${state.planDay>0?textAction('Choose a different idea','alternatives','refresh'):''}</div>`:`<div class="plan-empty"><div class="empty-art">${icon('calendar')}</div><h2>A little room<br>for inspiration.</h2><p>Nothing planned here yet. Prepare one idea that fits your interests, or save today’s idea for this day.</p>${primary('Prepare an idea for this day','prepare-plan','sparkle')}${textAction('Save today’s idea here','save-today-here','bookmark')}</div>`}<p class="plan-note">${p&&state.planDay>0?'Your idea is saved for this day. You can change it without changing Today.':'Keep it light. Planning ahead is optional.'}</p></div>`;}
function settingsRow(action,title,subtitle,symbol='right'){return `<button class="settings-row" data-action="${action}"><div class="settings-copy"><strong>${title}</strong><span>${escapeText(subtitle)}</span></div>${icon(symbol)}</button>`;}
function youView(){return `${header('You')}<div class="creator-card"><span class="profile-avatar">${initial()}</span><div><h3>${escapeText(state.name||'Iris')}</h3><p>A little room for your creative life.</p></div>${textAction('Edit','edit-profile')}</div><div class="creator-stats"><span><strong>${state.history.length}</strong> posts marked</span><span><strong>${Object.keys(state.plans).length}</strong> ideas saved</span><span><strong>${state.interests.size}</strong> interests</span></div><div class="settings-group"><div class="eyebrow">Make it feel like you</div>${settingsRow('interests','Interests & style',[...state.interests].join(' · ')||'Add what you enjoy')}${settingsRow('production','Content preferences',`${state.time} · ${state.voice} · ${state.format}`)}${settingsRow('voice','Creator voice',`${state.tone} · Your own words`)}${settingsRow('context','Current reads & watches',state.context||'Optional · what is on your mind?')}${settingsRow('references','References',state.references.length?`${state.references.length} saved inspiration links`:'Optional · add a post or creator you love')}<p class="profile-note">Your daily idea is already usable. These details can wait until you want to add them.</p></div><div class="settings-group"><div class="eyebrow">Your creative days</div>${settingsRow('history','Recent posts',state.history.length?`${state.history.length} marked as posted`:'Your finished ideas will show up here')}${settingsRow('reminders','Daily reminder',state.reminder?`On · ${state.reminderTime}`:'Off · choose a quiet moment')}</div><div class="settings-group"><div class="eyebrow">Account & help</div>${settingsRow('account','Account & privacy','Apple account · your data choices')}${settingsRow('tour','How it works','A quick guide to your daily idea')}${settingsRow('onboarding','Replay onboarding','See the welcome and optional setup again')}</div>`;}
const choiceList=(key,choices)=>`<div class="choice-list">${choices.map(([value,label,description,symbol])=>`<button class="choice-card" data-set="${key}" data-value="${value}" aria-pressed="${state[key]===value}">${icon(symbol||'check')}<span><strong>${label}</strong>${description?`<small>${description}</small>`:''}</span>${state[key]===value?icon('check'):''}</button>`).join('')}</div>`;
function preferencesView(){
  const titles={interests:'Interests & style',production:'Content preferences',voice:'Creator voice',context:'Current reads & watches',references:'References',reminders:'Daily reminder',account:'Account & privacy',profile:'Your profile'};
  let content='';
  if(state.preference==='interests')content=`<p class="field-help">Choose things you naturally notice, talk about, or enjoy.</p>${topicButtons(state.interests)}<label class="field-label" for="custom-topic">Something else you love</label><div class="inline-actions"><input class="field-input" id="custom-topic" data-input="customTopic" value="${escapeText(state.customTopic)}" placeholder="e.g. architecture" maxlength="50"><button class="text-action" data-action="add-topic">Add</button></div><label class="field-label">Where are you starting?</label><div class="starting-point">${['Just starting','Already posting'].map(x=>`<button data-set="startingPoint" data-value="${x}" aria-pressed="${state.startingPoint===x}">${x}</button>`).join('')}</div><div class="reason-note"><p>New preferences shape the next idea you prepare. Your current idea stays ready.</p></div>`;
  if(state.preference==='production')content=`<p class="field-help">Make the plan fit your day, your phone, and your comfort level.</p><label class="field-label">Time to create</label>${choiceList('time',[['5 min','5 minutes','A quick clip or a photo','clock'],['10 min','10 minutes','A few simple shots','clock'],['20 min','20 minutes','A little more room to make it yours','clock']])}<label class="field-label">How you like to record</label>${choiceList('voice',[['Voiceover','Voiceover','Film the moment. Add your words later.','mic'],['Talking to camera','Talking to camera','Tell it in your own words.','camera'],['No talking','No talking','Use on-screen text and everyday footage.','text']])}<label class="field-label">Preferred format</label>${choiceList('format',[['Reel','Short video','A simple vertical video','film'],['Story','Story','One small moment','camera'],['Photo post','Photo post','A photo and a few good words','book']])}`;
  if(state.preference==='voice')content=`<p class="field-help">Choose a direction. Your script stays editable, and you can change this whenever you like.</p><div class="taste-grid">${[['Thoughtful','A small thing that stayed with me.','A little reflective, with room to breathe.'],['Warm & casual','Okay, this made my day a little better.','Like telling a friend.'],['Direct & useful','Here is one thing I would do again.','Clear, practical, and to the point.']].map(([tone,quote,description])=>`<button class="taste-card" data-set="tone" data-value="${tone}" aria-pressed="${state.tone===tone}"><span class="eyebrow">${tone}</span><blockquote>“${quote}”</blockquote><small>${description}</small>${state.tone===tone?icon('check'):''}</button>`).join('')}</div><div class="reason-note"><span class="eyebrow">You have the last word</span><p>Change any line before recording. You do not need a voice recording or a detailed questionnaire.</p></div>`;
  if(state.preference==='context')content=`<p class="field-help">A book, a film, a place, or a small moment. Add something you might want to share.</p><label class="field-label" for="context-note">What is on your mind?</label><textarea class="field-input context-input" id="context-note" data-input="context" rows="7" placeholder="I just finished a book I nearly gave up on…" maxlength="1200">${escapeText(state.context)}</textarea><p class="field-help">Optional. You can keep using your daily idea without writing anything.</p>`;
  if(state.preference==='references')content=`<p class="field-help">Save a post or creator you like. Think of it as inspiration, not a style you have to copy.</p><div class="reference-list">${state.references.length?state.references.map((r,i)=>`<div class="reference-item">${icon('bookmark')}<span><strong>${escapeText(r.name)}</strong><small>${escapeText(new URL(r.url).hostname)}</small></span><button class="icon-btn" data-remove-reference="${i}" aria-label="Remove ${escapeText(r.name)}">${icon('close')}</button></div>`).join(''):`<div class="reference-empty">${icon('bookmark')}<p>A little collection starts here.</p></div>`}</div><label class="field-label" for="reference-name">A name to remember it by</label><input class="field-input" id="reference-name" data-input="referenceName" value="${escapeText(state.referenceName)}" placeholder="A creator whose stories I love" maxlength="80"><label class="field-label" for="reference-url">Post or profile link</label><input class="field-input" id="reference-url" type="url" data-input="referenceUrl" value="${escapeText(state.referenceUrl)}" placeholder="https://…">${secondary('Add inspiration','save-reference')}<p class="field-help">Links stay in this preview. No account connection or import is performed.</p>`;
  if(state.preference==='reminders')content=`<p class="field-help">A quiet nudge, at a time that suits you.</p><div class="settings-row"><div class="settings-copy"><strong>Remind me each day</strong><span>Your idea is ready when you are.</span></div><button role="switch" aria-label="Daily reminder" aria-checked="${state.reminder}" class="text-action" data-action="toggle-reminder">${state.reminder?'On':'Off'}</button></div><label class="field-label" for="reminder-time">Your preferred time</label><input class="field-input" id="reminder-time" data-input="reminderTime" type="time" value="${state.reminderTime}"><p class="demo-notice">This previews the setting. It does not schedule a device notification.</p>`;
  if(state.preference==='profile')content=`<p class="field-help">A small personal detail. Everything else can wait.</p><label class="field-label" for="creator-name">Your name</label><input class="field-input" id="creator-name" data-input="name" value="${escapeText(state.name)}" maxlength="50" autocomplete="given-name"><div class="privacy-card">${icon('user')}<div><strong>Signed in with Apple</strong><p>Sample account for this preview.</p></div></div>`;
  if(state.preference==='account')content=`<div class="privacy-card">${icon('user')}<div><strong>${escapeText(state.name||'Iris')}</strong><p>Apple account · sample sign-in</p></div></div><label class="field-label">Your data</label><div class="reason-note"><p>Ideas, preferences, saved days, and posts you mark complete belong together in your account.</p></div><div class="privacy-card"><div><strong>Your social accounts</strong><p>No connection is required to get an idea. Record and post in your usual apps.</p></div></div><div class="privacy-card"><div><strong>Control your preferences</strong><p>Edit your interests or remove an inspiration link at any time.</p></div></div>${secondary('Restart sign-in preview','onboarding')}<p class="demo-notice">All data here stays in memory. This preview does not sign in, export, delete, or publish through an external service.</p>`;
  return `<div class="screen-topline"><button class="icon-btn" data-action="you" aria-label="Back to You">${icon('left')}</button><h2>${titles[state.preference]}</h2></div><div class="preferences-page">${content}</div>`;
}
function skippedView(){return `<div class="success-content"><div class="success-mark">${icon('sun')}</div><h2>No rush today.</h2><p>Taking a day off is a valid choice.<br>Your idea stays here for when you want it.</p>${primary('Back to my idea','back-ready')}${textAction('Leave something ready for another day','save-plan','bookmark')}</div>`;}
function getScreen(){if(state.scenario==='onboarding')return state.onboardingStep==='welcome'?welcomeView():setupView();if(state.screen==='plan')return planView();if(state.screen==='you')return youView();if(state.screen==='preferences')return preferencesView();if(state.scenario==='empty')return emptyView();if(state.stage==='preparing')return preparingView();if(state.scenario==='error')return errorView();if(state.stage==='film')return filmView();if(state.stage==='post')return postView();if(state.stage==='posted')return successView();if(state.stage==='saved')return savedView();if(state.stage==='skipped')return skippedView();return readyViews[state.variant]();}
function dock(){if(state.scenario==='onboarding'&&state.onboardingStep==='welcome')return `<div class="stage-dock setup-footer welcome-footer">${welcomeActions()}</div>`;if(state.scenario==='onboarding'&&state.onboardingStep==='topics')return `<div class="stage-dock setup-footer">${primary('Show my first idea','first-idea','sparkle')}${textAction('Set up later','skip-setup')}</div>`;if(state.screen==='preferences')return `<div class="stage-dock setup-footer">${primary('Save preferences','save-preferences','check')}</div>`;if(state.screen!=='today'||state.scenario!=='ready')return '';if(state.stage==='ready')return `<div class="stage-dock daily-action-dock">${readyAction()}</div>`;if(state.stage==='film'){const last=state.shot===current().shots.length-1;return `<div class="stage-dock">${primary(last?'Shot done · get post text':'Shot done · next shot','shot-done','check')}${textAction('I already have my footage','post')}</div>`;}if(state.stage==='post')return `<div class="stage-dock">${primary('I’ve posted this','mark-posted','check')}<p style="font-size:10px;text-align:center;color:var(--muted);margin:9px 0 1px">This records your update. It doesn’t publish a post.</p></div>`;return '';}
function route(){const u=new URL(location.href);u.searchParams.set('variant',state.variant);const flow=state.scenario==='onboarding'?'onboarding':['you','preferences'].includes(state.screen)?'you':state.screen==='plan'?'plan':'today';if(flow==='today')u.searchParams.delete('flow');else u.searchParams.set('flow',flow);if(state.scenario==='onboarding'&&state.onboardingStep==='topics')u.searchParams.set('step','setup');else u.searchParams.delete('step');if(state.compare)u.searchParams.set('compare','1');else u.searchParams.delete('compare');history.replaceState(null,'',u);}
function render({top=true}={}){
  const oldScroll=app.querySelector('.app-scroll')?.scrollTop||0;
  phone.className=`phone theme-${state.variant}`;
  app.innerHTML=`<div class="app-scroll">${getScreen()}</div>${dock()}${state.scenario==='onboarding'||state.stage==='preparing'?'':nav()}`;
  if(!top)app.querySelector('.app-scroll').scrollTop=oldScroll;
  const d=directions[state.variant],n=Object.keys(directions).indexOf(state.variant)+1;
  document.querySelector('#direction-key').textContent=`DIRECTION 0${n} / 04`;
  document.querySelector('#direction-name').textContent=d.name;
  document.querySelector('#direction-description').textContent=d.description;
  document.querySelector('#direction-thesis').textContent=d.thesis;
  document.querySelector('#detail-points').innerHTML=d.points.map(([title,text],i)=>`<div class="detail-item"><span class="detail-num">0${i+1}</span><div><strong>${title}</strong><p>${text}</p></div></div>`).join('');
  document.querySelectorAll('[data-variant]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.variant===state.variant));
  document.querySelectorAll('[data-scenario]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.scenario===state.scenario));
  const journey=state.scenario==='onboarding'?'onboarding':state.screen==='preferences'?'you':state.screen;
  document.querySelectorAll('[data-journey]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.journey===journey));
  document.querySelector('#device-state').textContent=state.scenario==='onboarding'?`Onboarding · ${state.onboardingStep==='welcome'?'Welcome':'Optional setup'}`:state.scenario==='empty'?'Today · No idea yet':state.scenario==='error'?'Today · Retry an idea':state.screen==='plan'?`Plan · ${days[state.planDay].name}`:state.screen==='you'||state.screen==='preferences'?'You · Optional preferences':`Today · ${{ready:'Ready to begin',preparing:'Preparing an idea',film:'Filming step '+(state.shot+1),post:'Copy and post',posted:'Posted',saved:'Saved for another day',skipped:'Taking a day off'}[state.stage]}`;
  document.title=`${d.name} — ContentHelper prototype`;
  route();
}
function toast(message){clearTimeout(toastTimeout);const t=document.querySelector('#toast');t.textContent=message;t.classList.add('is-visible');toastTimeout=setTimeout(()=>t.classList.remove('is-visible'),2300);}
function setVariant(variant){state.variant=variant;if(sheet.open)sheet.close();render();if(state.compare)renderComparison();console.info('ContentHelper prototype',{variant,screen:state.screen,stage:state.stage,idea:state.idea,shot:state.shot,scenario:state.scenario});}
function abandonPreferences(){if(state.preferenceSnapshot){Object.assign(state,state.preferenceSnapshot);state.preferenceSnapshot=null;}}
function journey(name){if(state.screen==='preferences')abandonPreferences();if(sheet.open)sheet.close();state.screen=name==='onboarding'?'today':name;state.scenario=name==='onboarding'?'onboarding':'ready';if(name==='onboarding')state.onboardingStep='welcome';render();}
function reset(){preparationToken++;state.preferenceSnapshot=null;sheetDraft=null;Object.assign(state,{screen:'today',stage:'ready',scenario:'ready',idea:'book',done:new Set(),shot:0,planDay:0,plans:{},history:[],interests:new Set(['Books']),setupInterests:new Set(),time:'10 min',voice:'Voiceover',format:'Reel',tone:'Thoughtful',platform:'Instagram',startingPoint:'Just starting',name:'Iris',context:'',customTopic:'',references:[],referenceName:'',referenceUrl:'',reminder:false,reminderTime:'09:00',captionDrafts:{},scriptDrafts:{},includeTags:true,firstIdea:false,alternativeTarget:null});if(sheet.open)sheet.close();render();toast('Preview reset. Your idea is ready.');}
function personalizedIdea(){let id=[...state.interests].map(x=>topicIdeas[x]).find(Boolean)||'routine';const p=packages[id];if(state.format==='Photo post'){const key=`photo-${id}`;packages[key]={...p,title:`A small thought about ${id==='book'?'a book':id==='routine'?'my day':p.label.split(' &')[0].toLowerCase()}`,format:'Photo post',duration:0,minutes:2,shots:[],why:'Use a photo you already have. The words are ready.'};id=key;}else if(state.format==='Story'||(state.time==='5 min'&&p.minutes>5)){const key=`quick-${id}`;packages[key]={...p,format:state.format==='Story'?'Story':'Reel',duration:10,minutes:3,shots:[{...p.shots[0],duration:'0–10 sec',words:p.hook}],why:'One familiar moment. A single clip. Keep it small today.'};id=key;}return id;}
function selectIdea(id){preparationToken++;state.idea=id;state.stage='ready';state.screen='today';state.scenario='ready';state.shot=0;state.done=new Set();state.alternativeTarget=null;if(sheet.open)sheet.close();render();}
function prepareIdea(first=false){const token=++preparationToken;state.screen='today';state.scenario='ready';state.stage='preparing';state.firstIdea=first||state.firstIdea;render();setTimeout(()=>{if(token!==preparationToken)return;selectIdea(personalizedIdea());},900);}
function showSheet(content){if(!sheet.open)lastFocused=document.activeElement;sheet.className=`sheet-dialog theme-${state.variant}`;sheet.innerHTML=`<div class="sheet-handle" aria-hidden="true"></div>${content}`;positionSheet();if(!sheet.open)sheet.showModal();if(!keyboardAction&&!matchMedia('(prefers-reduced-motion: reduce)').matches)sheet.animate([{transform:'translateY(18px)',opacity:0},{transform:'translateY(0)',opacity:1}],{duration:190,easing:'cubic-bezier(.32,.72,0,1)'});}
function positionSheet(){const r=phone.getBoundingClientRect();sheet.style.setProperty('--dialog-left',`${r.left+7}px`);sheet.style.setProperty('--dialog-bottom',`${Math.max(12,innerHeight-r.bottom+7)}px`);sheet.style.setProperty('--dialog-width',`${r.width-14}px`);}
const sheetHeader=(title)=>`<div class="sheet-heading"><h2 id="sheet-title">${title}</h2><button class="icon-btn" data-action="close-sheet" aria-label="Close sheet">${icon('close')}</button></div>`;
function alternatives(){state.alternativeTarget=state.screen==='plan'&&state.planDay>0?state.planDay:null;showSheet(`${sheetHeader(state.alternativeTarget?'Another idea for this day':'Something easier?')}<p class="sheet-description">Choose what fits your day. The complete words and filming plan come with it.</p>${[['story','camera','A 10-second story','One clip. Two minutes. A small win from today.'],['caption','text','A caption and a photo','Use a photo you already have. No filming.'],['routine','refresh','A different Reel','A quiet daily reset. Five minutes to film.']].map(([id,symbol,title,desc])=>`<button class="alternative" data-idea="${id}"><span class="alt-icon">${icon(symbol)}</span><span class="alt-copy"><strong>${title}</strong><small>${desc}</small></span>${icon('right')}</button>`).join('')}${state.alternativeTarget?'':`<div class="sheet-divider"></div><div class="sheet-tools">${textAction('Save this for another day','save-plan','bookmark')}${textAction('Take today off','skip-today')}</div>`}`);}
function preferences(kind){if(state.screen==='preferences')abandonPreferences();state.preferenceSnapshot=structuredClone(Object.fromEntries(['interests','startingPoint','time','voice','format','tone','platform','name','context','customTopic','references','referenceName','referenceUrl','reminder','reminderTime'].map(key=>[key,state[key]])));if(sheet.open)sheet.close();state.preference=kind;state.screen='preferences';state.scenario='ready';render();}
function scriptSheet(){const p=current();showSheet(`${sheetHeader('Your full script')}<p class="sheet-description">${p.title} · ${p.duration||'PHOTO'}${p.duration?' seconds':''}</p>${(p.shots.length?p.shots:[{duration:'Caption',words:p.caption,name:'Your words'}]).map((s,i)=>`<div class="script-part"><span class="eyebrow">${p.shots.length?String(i+1).padStart(2,'0'):''}</span><div><span class="eyebrow">${s.duration} · ${s.name}</span><p>“${escapeText(s.words)}”</p></div></div>`).join('')}${primary('Copy full script','copy-script','copy')}${textAction('Edit the script','edit-script','text')}`);}
function scriptEditor(){const p=current();if(!p.shots.length){captionEditor();return;}sheetDraft={kind:'script',id:state.idea,shots:p.shots.map(s=>s.words)};showSheet(`${sheetHeader('Make the script yours')}<p class="sheet-description">Keep the structure. Change any line so it sounds like you.</p>${p.shots.map((s,i)=>`<label class="field-label" for="script-shot-${i}">Shot ${i+1} · ${s.name}</label><textarea class="field-input script-edit" id="script-shot-${i}" data-script-shot="${i}" rows="3" maxlength="1500">${escapeText(s.words)}</textarea>`).join('')}${primary('Save script','save-script','check')}`);}
function captionEditor(){sheetDraft={kind:'caption',id:state.idea,value:current().caption};showSheet(`${sheetHeader('Your words, your way')}<p class="sheet-description">A starting point, not a rule. Change anything you like.</p><label class="field-label" for="caption-draft">Caption</label><textarea class="field-input script-edit" id="caption-draft" data-caption-input rows="9" maxlength="3000">${escapeText(current().caption)}</textarea><span class="field-help" id="caption-count">${current().caption.length} characters</span>${primary('Save caption','save-caption','check')}`);}
function socialPreview(){const p=current();showSheet(`${sheetHeader(`${state.platform} preview`)}<p class="sheet-description">A rough look at your post before you share.</p><article class="social-preview"><div class="social-header"><span class="profile-avatar">${initial()}</span><span><strong>${escapeText(state.name||'Iris')}</strong><small>${p.format} · Your post</small></span></div><div class="social-art">${art(p.art,state.variant==='C')}</div><div class="social-copy">${escapeText(captionText())}</div></article>${textAction('Back to the caption','close-sheet')}<p class="demo-notice">This is a visual preview. It does not publish a post.</p>`);}
function savePlanSheet(){showSheet(`${sheetHeader('Leave an idea ready')}<p class="sheet-description">Save “${current().title}” for a day that suits you.</p><div class="choice-list">${days.slice(1).map((d,i)=>`<button class="choice-card" data-save-day="${i+1}" aria-pressed="${state.saveDay===i+1}">${icon('calendar')}<span><strong>${d.name} · ${d.date} October</strong><small>${state.plans[i+1]?packages[state.plans[i+1]].title:'Nothing planned yet'}</small></span>${state.saveDay===i+1?icon('check'):''}</button>`).join('')}</div>${state.plans[state.saveDay]&&state.plans[state.saveDay]!==state.idea?`<div class="reason-note"><p>This day already has an idea. Choose another day to keep both.</p></div>`:primary(`Save for ${days[state.saveDay].name.toLowerCase()}`,'confirm-save-plan','bookmark')}`);}
function saveForDay(day){if(state.plans[day]&&state.plans[day]!==state.idea){state.saveDay=day;savePlanSheet();return;}state.plans[day]=state.idea;state.lastSavedDay=day;state.stage='saved';state.screen='today';state.scenario='ready';if(sheet.open)sheet.close();render();}
function planIdeaSheet(){const p=packages[state.plans[state.planDay]];showSheet(`${sheetHeader('Ready for '+days[state.planDay].name.toLowerCase())}<p class="sheet-description">${p.title}</p>${art(p.art,state.variant==='C')}${meta(p)}<div class="instruction-block"><span class="eyebrow">Your opening line</span><p>“${p.hook}”</p></div>${p.shots.map((s,i)=>`<div class="script-part"><span class="eyebrow">0${i+1}</span><div><strong>${s.name}</strong><p>${s.instruction}</p></div></div>`).join('')}<div class="instruction-block"><span class="eyebrow">Caption</span><p>${escapeText(p.caption)}</p></div>${primary('Use this idea today','use-plan-today')}${textAction('Back to Plan','close-sheet')}`);}
function historySheet(){showSheet(`${sheetHeader('Your recent posts')}${state.history.length?`<p class="sheet-description">Ideas you marked as posted. Keep the words for another day.</p><div class="history-list">${state.history.map(id=>`<button class="history-item" data-history="${id}"><span class="shot-thumb">${art(packages[id].art)}</span><span><strong>${packages[id].title}</strong><small>Marked posted · 2 October</small></span>${icon('right')}</button>`).join('')}</div>`:`<div class="reference-empty">${icon('sparkle')}<p>Your first small beginning is waiting on Today.</p></div>${primary('Open today’s idea','history-today')}`}`);}
function historyDetail(id){const p=packages[id];showSheet(`${sheetHeader('A post to keep')}<p class="sheet-description">${p.title} · Marked posted, 2 October</p>${art(p.art)}<div class="instruction-block"><span class="eyebrow">Your saved caption</span><p>${escapeText(state.captionDrafts[id]??p.caption)}</p></div>${textAction('Back to recent posts','history')}`);}
function tourSheet(){const pages=[['One idea. Already ready.','Today gives you the title, opening line, and time to make it. You can begin without a planning session.','sparkle'],['Follow one shot at a time.','See what to film, what to say, and the text to add. Record with your phone, then mark each shot done.','film'],['Make the words yours.','Edit the script or caption. Copy your words and post in your usual app. Mark it posted when you finish.','copy']];const [title,desc,symbol]=pages[state.tourStep];showSheet(`${sheetHeader('A quick tour')}<div class="tour-card"><div class="success-mark">${icon(symbol)}</div><span class="eyebrow">${state.tourStep+1} of 3</span><h2>${title}</h2><p>${desc}</p></div>${primary(state.tourStep===2?'Got it':'Next tip',state.tourStep===2?'close-sheet':'tour-next')}${state.tourStep<2?textAction('Skip the tour','close-sheet'):''}`);}
async function copy(kind,button){const p=current(),value=kind==='caption'?captionText(p):p.shots.map(s=>s.words).join('\n\n')||p.caption;try{if(navigator.clipboard&&location.protocol!=='file:')await navigator.clipboard.writeText(value);else{const ta=document.createElement('textarea');ta.value=value;ta.style.cssText='position:fixed;left:0;top:0;opacity:0';(sheet.open?sheet:document.body).append(ta);ta.select();if(!document.execCommand('copy'))throw Error('Clipboard unavailable');ta.remove();}if(button)button.innerHTML=icon('check')+' Copied';toast(kind==='caption'?'Caption copied. Ready for your usual posting app.':'Your script is copied.');}catch{toast('Select the text to copy it in this browser.');}}
function renderComparison(){const old={screen:state.screen,stage:state.stage,scenario:state.scenario,firstIdea:state.firstIdea};Object.assign(state,{screen:'today',stage:'ready',scenario:'ready',firstIdea:false});document.querySelector('#comparison').innerHTML=`<div class="comparison-heading"><h1>One idea. Four ways to start.</h1><p>Compare Today, then try onboarding and the complete creator workflow in each direction.</p></div><div class="comparison-grid">${Object.entries(directions).map(([key,d])=>`<article class="comparison-item"><h2>${key} · ${d.name}</h2><p>${d.description.split('.')[0]}.</p><div class="mini-phone theme-${key}"><div class="device-status"><span>9:41</span><div class="device-island"></div><span>▮▮▮</span></div><div class="app"><div class="app-scroll">${readyViews[key]()}</div><div class="stage-dock daily-action-dock">${readyAction(key)}</div>${nav()}</div></div><button data-open-variant="${key}">Try ${d.name} ${icon('arrow')}</button></article>`).join('')}</div>`;Object.assign(state,old);}
function compareToggle(){state.compare=!state.compare;document.body.classList.toggle('is-comparing',state.compare);document.querySelector('#workspace').hidden=state.compare;document.querySelector('#comparison').hidden=!state.compare;document.querySelector('[data-action="compare"]').innerHTML=state.compare?'Back to interactive preview ↗':'Compare all four ↗';if(state.compare)renderComparison();route();}
function action(name,button){switch(name){
  case 'today':case 'plan':case 'you':journey(name);break;
  case 'onboarding':journey('onboarding');break;
  case 'film':state.stage='film';render();break;
  case 'back-ready':state.stage='ready';render();break;
  case 'post':state.stage='post';render();break;
  case 'shot-done':state.done.add(state.shot);if(state.shot<current().shots.length-1)state.shot++;else state.stage='post';render();break;
  case 'mark-posted':state.stage='posted';if(!state.history.includes(state.idea))state.history.push(state.idea);render();break;
  case 'undo-posted':state.stage='post';state.history=state.history.filter(x=>x!==state.idea);render();toast('Posted status undone.');break;
  case 'alternatives':alternatives();break;
  case 'script':scriptSheet();break;
  case 'edit-script':scriptEditor();break;
  case 'save-script':if(sheetDraft?.kind==='script')state.scriptDrafts[sheetDraft.id]=[...sheetDraft.shots];sheetDraft=null;sheet.close();render({top:false});toast('Your script is saved in this preview.');break;
  case 'edit-caption':captionEditor();break;
  case 'save-caption':if(sheetDraft?.kind==='caption')state.captionDrafts[sheetDraft.id]=sheetDraft.value;sheetDraft=null;sheet.close();render({top:false});toast('Your caption is saved in this preview.');break;
  case 'copy-caption':copy('caption',button);break;
  case 'copy-script':copy('script',button);break;
  case 'toggle-tags':state.includeTags=!state.includeTags;render({top:false});break;
  case 'social-preview':socialPreview();break;
  case 'close-sheet':sheet.close();lastFocused?.isConnected&&lastFocused.focus();break;
  case 'save-plan':state.saveDay=state.planDay>0?state.planDay:1;savePlanSheet();break;
  case 'confirm-save-plan':saveForDay(state.saveDay);break;
  case 'save-today-here':saveForDay(state.planDay);break;
  case 'skip-today':sheet.close();state.stage='skipped';render();break;
  case 'plan-tomorrow':if(sheet.open)sheet.close();state.screen='plan';state.scenario='ready';state.planDay=1;render();break;
  case 'open-saved-day':state.screen='plan';state.planDay=state.lastSavedDay;render();break;
  case 'open-plan-idea':if(state.planDay===0){state.screen='today';state.stage=state.history.includes(state.idea)?'posted':'ready';render();}else planIdeaSheet();break;
  case 'use-plan-today':selectIdea(state.plans[state.planDay]);toast('This is now your active idea for today.');break;
  case 'prepare-plan':state.plans[state.planDay]=personalizedIdea();render();toast('One idea is ready for the selected day.');break;
  case 'prepare':prepareIdea();break;
  case 'first-idea':state.interests=new Set(state.setupInterests);prepareIdea(true);break;
  case 'preview-sign-in':state.onboardingStep='topics';render();break;
  case 'onboarding-back':state.onboardingStep='welcome';render();break;
  case 'skip-setup':state.interests=new Set();prepareIdea(true);break;
  case 'use-starter':selectIdea('routine');break;
  case 'interests':case 'production':case 'voice':case 'context':case 'references':case 'reminders':case 'account':preferences(name);break;
  case 'edit-profile':preferences('profile');break;
  case 'add-topic':if(state.customTopic.trim()){state.interests.add(state.customTopic.trim());state.customTopic='';render({top:false});}break;
  case 'save-preferences':state.preferenceSnapshot=null;state.screen='you';render();toast('Preferences saved in this preview.');break;
  case 'save-reference':{let url;try{url=new URL(state.referenceUrl);if(!['http:','https:'].includes(url.protocol))throw Error('Unsupported URL');}catch{toast('Add a full link starting with https://.');break;}state.references.push({name:state.referenceName.trim()||url.hostname,url:url.href});state.referenceName='';state.referenceUrl='';render({top:false});toast('Inspiration saved in this preview.');break;}
  case 'toggle-reminder':state.reminder=!state.reminder;render({top:false});break;
  case 'history':historySheet();break;
  case 'history-today':sheet.close();journey('today');break;
  case 'tour':state.tourStep=0;tourSheet();break;
  case 'tour-next':state.tourStep++;tourSheet();break;
  case 'reset':reset();break;
  case 'compare':compareToggle();break;
  case 'previous-variant':case 'next-variant':{const keys=Object.keys(directions),i=keys.indexOf(state.variant);setVariant(keys[(i+(name==='next-variant'?1:3))%4]);break;}
}}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;
  if(button.dataset.variant){setVariant(button.dataset.variant);return;}
  if(button.dataset.openVariant){setVariant(button.dataset.openVariant);if(state.compare)compareToggle();return;}
  if(button.dataset.journey){journey(button.dataset.journey);return;}
  if(button.dataset.scenario){if(state.screen==='preferences')abandonPreferences();preparationToken++;state.scenario=button.dataset.scenario;state.screen='today';state.stage='ready';render();return;}
  if(button.dataset.planDay!==undefined){state.planDay=Number(button.dataset.planDay);render();return;}
  if(button.dataset.shot!==undefined){state.shot=Number(button.dataset.shot);state.stage='film';render();return;}
  if(button.dataset.saveDay){state.saveDay=Number(button.dataset.saveDay);savePlanSheet();return;}
  if(button.dataset.idea){if(state.alternativeTarget!==null){state.plans[state.alternativeTarget]=button.dataset.idea;state.alternativeTarget=null;sheet.close();render();toast('The selected day has a new idea.');}else{selectIdea(button.dataset.idea);toast('Your new idea is ready.');}return;}
  if(button.dataset.interest){const selected=button.dataset.setup==='true'?state.setupInterests:state.interests;selected.has(button.dataset.interest)?selected.delete(button.dataset.interest):selected.add(button.dataset.interest);render({top:false});return;}
  if(button.dataset.set){state[button.dataset.set]=button.dataset.value;render({top:false});return;}
  if(button.dataset.removeReference!==undefined){state.references.splice(Number(button.dataset.removeReference),1);render({top:false});return;}
  if(button.dataset.history){historyDetail(button.dataset.history);return;}
  if(button.dataset.action)action(button.dataset.action,button);
});
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.input)state[input.dataset.input]=input.value;if(input.hasAttribute('data-caption-input')){if(sheetDraft?.kind==='caption')sheetDraft.value=input.value;document.querySelector('#caption-count').textContent=`${input.value.length} characters`;}if(input.dataset.scriptShot!==undefined){if(sheetDraft?.kind==='script')sheetDraft.shots[Number(input.dataset.scriptShot)]=input.value;}});
document.addEventListener('keydown',event=>{keyboardAction=true;document.documentElement.classList.add('no-motion');if(event.key!=='ArrowLeft'&&event.key!=='ArrowRight')return;if(sheet.open||event.target.closest('input,textarea,[contenteditable],select'))return;event.preventDefault();action(event.key==='ArrowRight'?'next-variant':'previous-variant');});
document.addEventListener('pointerdown',()=>{keyboardAction=false;document.documentElement.classList.remove('no-motion');});
sheet.addEventListener('close',()=>{sheetDraft=null;});
sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)sheet.close();}});
window.addEventListener('resize',()=>{if(sheet.open)positionSheet();});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);state.variant=directions[p.get('variant')]?p.get('variant'):'A';journey(p.get('flow')||'today');});
render();
if(query.get('compare')==='1')compareToggle();
